import json
# Search the full JSON for any reference to NBER or journal publication dates
with open('/app/resources/treasury_bulletin_1992_06.json', 'r') as f:
    data = json.load(f)

def search_elements(elements, depth=0, max_depth=5):
    if depth > max_depth:
        return
    if isinstance(elements, dict):
        for k, v in elements.items():
            if isinstance(v, (dict, list)):
                search_elements(v, depth+1, max_depth)
            elif isinstance(v, str) and any(term in v.upper() for term in ['NBER', 'JOURNAL', 'PUBLISH', 'QUARTERLY', 'REVIEW', 'ECONOMIC']):
                print(f"Found at depth {depth}, key '{k}': {v[:200]}")
    elif isinstance(elements, list):
        for item in elements:
            search_elements(item, depth+1, max_depth)

search_elements(data)
