import json
# Search comprehensively for any mention of Ins and Outs or NBER across all content
with open('/app/resources/treasury_bulletin_1992_06.json', 'r') as f:
    data = json.load(f)

def deep_search(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items():
            deep_search(v, f"{path}.{k}")
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            deep_search(item, f"{path}[{i}]")
    elif isinstance(obj, str):
        if 'ins' in obj.lower() and 'out' in obj.lower():
            print(f"Found: {path} = {obj[:500]}")

deep_search(data)
